def parse_price(p):
    if p is None: return None
    try:
        s = str(p).replace('$', '').replace(',', '').strip()
        return float(s)
    except Exception:
        return None

def find_match(target, options):
    if not target or not options: return None
    t = str(target).lower().strip()
    for opt in options:
        o = str(opt).lower().strip()
        if t in o or o in t:
            return opt
    return None

def hook(ctx, nb):
    try:
        action = ctx.get("action", {})
        state = ctx.get("state", {})
        task = ctx.get("task", {})
        webshop = ctx.get("webshop", {})
    except Exception:
        return None
    tool = action.get("tool", "")
    if tool != "click_action": return None
    val_norm = action.get("value_normalized", "")
    if val_norm != "buy now": return None
    curr_p = parse_price(state.get("current_price", None))
    max_p = parse_price(state.get("price_max", None))
    if curr_p is not None and max_p is not None:
        if curr_p > max_p:
            return {"kind": "block_and_prompt", "message": "Price exceeds budget. Return to search."}
    selected = webshop.get("selected_attributes", [])
    selected_lower = [str(s).lower() for s in selected]
    clickables = state.get("clickables", [])
    req_color = task.get("required_color", None)
    if req_color:
        rc = str(req_color).lower().strip()
        is_sel = False
        for s in selected_lower:
            if rc in s or s in rc:
                is_sel = True
                break
        if not is_sel:
            match = find_match(req_color, clickables)
            if match:
                return {"kind": "rewrite_action", "action": "click[" + match + "]", "message": "Select color first."}
    req_size = task.get("required_size", None)
    if req_size:
        rs = str(req_size).lower().strip()
        is_sel = False
        for s in selected_lower:
            if rs in s or s in rs:
                is_sel = True
                break
        if not is_sel:
            match = find_match(req_size, clickables)
            if match:
                return {"kind": "rewrite_action", "action": "click[" + match + "]", "message": "Select size first."}
    req_mat = task.get("required_material", None)
    if req_mat:
        rm = str(req_mat).lower().strip()
        is_sel = False
        for s in selected_lower:
            if rm in s or s in rm:
                is_sel = True
                break
        if not is_sel:
            match = find_match(req_mat, clickables)
            if match:
                return {"kind": "rewrite_action", "action": "click[" + match + "]", "message": "Select material first."}
    return None
